  (gen_random_uuid(), 'ebiz@igennews.com', 'e.biz', 'Ritu Agarwal', '$argon2id$v=19$m=19456,t=2,p=1$qPd6IKfoz3jFz8B2h6UA1A$FOOpr4hXbo8/60MsN3ekPPiHR3sgYpNCgZX4sGqPH5Q', 'section_editor', 'Editorial', false, '{"headline": "Section Editor · Retail & E-Commerce, Tourism · iGEN News", "bio": "Ritu Agarwal edits iGEN News coverage of Retail & E-Commerce, Tourism, commissioning and shaping the desk''s reporting and setting the agenda across the beat. Ritu has run newsroom teams for over a decade.", "location": "New Delhi", "pronouns": "he/him", "visibility": "public", "verified": true, "available": true, "beats": ["Retail & E-Commerce", "Tourism"], "skills": ["Editing", "Commissioning", "Beat leadership", "News judgement", "Retail"], "languages": ["English", "Hindi", "Punjabi"], "social": [{"label": "X", "url": "https://x.com/ebiz"}, {"label": "LinkedIn", "url": "https://www.linkedin.com/in/ebiz"}], "contact": {"email": "ebiz@igennews.com"}, "experience": [{"title": "Retail Editor", "org": "iGEN News", "period": "2024–present"}, {"title": "Senior Editor", "org": "Reuters India", "period": "2018–2024"}], "education": [{"title": "Postgraduate Diploma, Journalism", "org": "ACJ Chennai", "year": "2010"}], "awards": [{"title": "Ramnath Goenka Excellence in Journalism (finalist)", "year": "2023"}], "editorials": [], "featured": {}, "avatar": "", "cover": ""}'::jsonb),
